{"code":"import { runSql } from '../servers/earnings/index.js';

// Precisamos calcular a queda trimestral a trimestral manualmente.
// Vamos buscar todos os trimestres de todas empresas dos EUA, ordenados por symbol e period_end
// e calcular a variação de um trimestre para o anterior.

const sql = `
  WITH ordered_quarters AS (
    SELECT 
      symbol, 
      name, 
      period_end, 
      revenue_usd_b,
      LAG(revenue_usd_b) OVER (PARTITION BY symbol ORDER BY period_end) as prev_revenue
    FROM v_quarter
    WHERE market = 'EUA'
  ),
  qoq_changes AS (
    SELECT 
      symbol,
      name,
      period_end,
      revenue_usd_b,
      prev_revenue,
      ROUND(((revenue_usd_b - prev_revenue) / prev_revenue) * 100, 2) as qoq_pct
    FROM ordered_quarters
    WHERE prev_revenue IS NOT NULL
  )
  SELECT * FROM qoq_changes 
  ORDER BY qoq_pct ASC 
  LIMIT 20
`;

const result = await runSql({ sql });
console.log("Maiores quedas trimestrais (QoQ):", JSON.stringify(result.rows, null, 2));
"}

